#include <iostream>
#include <algorithm>
#include <cstdio>

using namespace std;

struct Item {
    int value;
    int weight;
    double ratio; // value-to-weight ratio
};

const int max_items = 1000; // Set a maximum number of items
int wei; // Maximum weight
int n; // Number of items
Item items[max_items]; // Static array for items
int dp[100005]; // Static array for dp table

bool cmp(Item a, Item b) {
    return a.ratio > b.ratio; // Sort by highest ratio
}

int max_value() {
    fill(dp, dp + wei + 1, 0); // Resize dp table using fill
    for (int i = 0; i < n; i++) {
        for (int j = wei; j >= items[i].weight; j--) {
            dp[j] = max(dp[j], dp[j - items[i].weight] + items[i].value);
        }
    }
    return dp[wei];
}

void max_weight(int ans) {
    int w_min;
    for (int i = wei - 1; i >= 0; i--) {
        if(ans != dp[i]) {
            w_min = i + 1;
            break;
        }
    }
    cout << w_min << endl;
}

int main(void) {
    int cnt = 1;
    while (scanf("%d", &wei) == 1) {
        if (wei == 0) break;
        scanf("%d", &n);
        for(int i = 0; i < n; i++) {
            char ten;
            scanf("%d %c %d", &items[i].value, &ten, &items[i].weight);
            items[i].ratio = (double)items[i].value / items[i].weight; // Calculate ratio
        }
        sort(items, items + n, cmp); // Sort items by value-to-weight ratio
        cout << "Case " << cnt << ":" << endl;
        int ans = max_value();
        cout << ans << endl;
        max_weight(ans);
        cnt++;
    }
    return 0;
}

